onClick={async () => { try {
    const response = await fetch(`/api/support/messages/${encodeURIComponent(m.id)}/retry`, { method: 'POST' });
    if (!response.ok)
        throw new Error('Falha ao reenviar.');
    if (activeConversationId)
        await fetchMessages(activeConversationId, true);
}
catch {
    toastService.error('Mensagem não enviada', 'Verifique a conexão do WhatsApp e tente novamente.');
} }}

onClick={() => {
        setSelectedAction('ALL');
        setSelectedEntity('ALL');
        setStartDate('');
        setEndDate('');
        setSearchTerm('');
        setPage(1);
    }}

onClick={() => {
        if (!newExtraTenantId)
            return;
        setExtraMemberships(prev => [...prev, { tenantId: newExtraTenantId, role: newExtraRole }]);
        setNewExtraTenantId('');
    }}

onChange={e => {
        const nextType = e.target.value as EntryType;
        setType(nextType);
        if (!getFinancialCategories(nextType).includes(category)) {
            setCategory(nextType === 'ENTRADA' ? 'RECEBIMENTO_OPERACIONAL' : 'DESPESA_VARIAVEL');
        }
    }}

onChange={e => {
        const checked = e.target.checked;
        setIsPaid(checked);
        if (checked && !paymentDate)
            setPaymentDate(localDateInputValue());
    }}

onClick={() => {
        onNavigate('clients_360', { clientId: c.id, cpf: c.cpf });
        onClose();
    }}

onChange={(e) => {
        const env = e.target.value as 'homologation' | 'production';
        const defaultUrl = env === 'production'
            ? 'https://proposta.facta.com.br/sistemaPropostas/api'
            : 'https://desenvolvimento.facta.com.br/sistemaPropostas/api';
        setFactaConfig({ ...factaConfig, environment: env, baseUrl: defaultUrl });
    }}

onClick={() => {
        setEditingAutomation({
            id: rule.id,
            name: rule.name,
            description: rule.description || undefined,
            event: rule.event,
            conditions: Array.isArray(rule.conditions)
                ? { matchType: 'ALL', rules: rule.conditions }
                : rule.conditions,
            actions: rule.actions,
            active: rule.active,
        });
        setBuilderOpen(true);
    }}

onClick={() => {
        if (act.type === 'CREATE_PENDENCY') {
            handleCreatePendency(selectedInsight);
        }
        else if (act.targetUrl && onNavigateToView) {
            const view = act.targetUrl.replace('/', '').split('?')[0];
            onNavigateToView(view);
            setSelectedInsight(null);
        }
    }}

onChange={(e) => {
        const val = parseInt(e.target.value, 10);
        setSlaConfigs((prev) => prev.map((c) => (c.severity === cfg.severity ? { ...c, acknowledgeMinutes: val } : c)));
    }}

onChange={(e) => {
        const val = parseInt(e.target.value, 10);
        setSlaConfigs((prev) => prev.map((c) => (c.severity === cfg.severity ? { ...c, resolveMinutes: val } : c)));
    }}

onChange={e => {
        const file = e.target.files?.[0];
        e.target.value = '';
        if (file)
            handleFileSelected(file);
    }}

onClick={() => setRestoreModalConfig({
        isOpen: true,
        dataDump: snap.dataDump,
        snapshotName: `Snapshot de ${formatDate(snap.createdAt)} (${snap.stats.proposalsCount} propostas)`,
    })}

onClick={() => setDeleteModalConfig({
        isOpen: true,
        snapshotId: snap.id,
        snapshotName: snap.fileName,
    })}
